import numpy as np

d = 4
keys = np.eye(d)                        # 직교 키 4개
vals = np.arange(8.0).reshape(4, 2)     # 키마다 저장할 값 (d_v = 2)

def linear(S, k, v):  return S + np.outer(k, v)
def delta(S, k, v, beta=1.0):           # (I - β k kᵀ) S + β k vᵀ
    return S - beta * np.outer(k, k @ S) + beta * np.outer(k, v)

for name, upd in [("linear", linear), ("delta", delta)]:
    S = np.zeros((d, 2))
    for k, v in zip(keys, vals):
        S = upd(S, k, v)
    S = upd(S, keys[0], np.array([10.0, 10.0]))   # 키 0 의 값을 고쳐 쓴다
    print(f"{name:6s} 키0 읽기:", keys[0] @ S, " 키1 읽기:", keys[1] @ S)
